/* eslint-disable */
/* global WebImporter */

/**
 * glossary parser.
 * Block table (see blocks/glossary/README.md):
 *   row: background image only (search banner image)          [optional]
 *   row: intro (title, disclaimer, sub heading)                 single cell
 *   row: Search | <search field label>                          [optional]
 *   rows: term | definition                                     one per term, all letters
 *   row: outro content                                          single cell [optional]
 * Letter tabs are generated by the block, so the source tab list is dropped.
 *
 * Terms come from the A-Z tab panels: each .citi-rte__para-header paragraph is a
 * term ("Term:"; trailing colon dropped) and the following paragraphs/lists up to
 * the next header are its definition. Fallbacks: dl dt/dd, headings + siblings.
 *
 * Outro ("Additional Resources" icon tiles): the tiles need a columns layout, so
 * the content is pushed to params.fragments and the cell holds the fragment link
 * (the block loads /fragments/ links in place). Without params.fragments the
 * content stays inline.
 */

const CHROME = 'script, style, noscript, svg, cds-icon, button, input, label.search-warning, .ada-hidden, .sr-only, .visually-hidden, .cdk-visually-hidden, [aria-hidden="true"]:not(img)';

function textOf(el) {
  return (el ? el.textContent : '').replace(/\s+/g, ' ').trim();
}

function slugify(s) {
  return (s || '').toLowerCase().normalize('NFKD').replace(/[^\w\s-]/g, '').trim()
    .replace(/[\s_]+/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '');
}

function pagePath(params) {
  try {
    if (params && params.originalURL) return new URL(params.originalURL).pathname.replace(/\.html$/, '').replace(/\/$/, '');
  } catch (e) { /* ignore */ }
  return '';
}

function imgSrc(img) {
  const candidates = [img.getAttribute('src'), img.getAttribute('data-src'), (img.getAttribute('srcset') || '').split(/[\s,]+/)[0]];
  return candidates.find((s) => s && !/^data:/i.test(s)) || '';
}

function makeImg(document, img) {
  const src = img && imgSrc(img);
  if (!src) return null;
  const out = document.createElement('img');
  out.setAttribute('src', src);
  const alt = (img.getAttribute('alt') || '').trim();
  out.setAttribute('alt', /^image$/i.test(alt) ? '' : alt);
  return out;
}

/** Clean copy of a node: chrome removed, attributes stripped (href/src/alt kept). */
function clean(el) {
  const clone = el.cloneNode(true);
  clone.querySelectorAll(CHROME).forEach((n) => n.remove());
  clone.querySelectorAll('a').forEach((a) => {
    const href = (a.getAttribute('href') || '').trim();
    if (!href || /^javascript:/i.test(href)) a.replaceWith(...a.childNodes);
  });
  [clone, ...clone.querySelectorAll('*')].forEach((n) => {
    [...n.attributes].forEach((a) => {
      if (!['href', 'target', 'src', 'alt'].includes(a.name)) n.removeAttribute(a.name);
    });
  });
  clone.querySelectorAll('span').forEach((n) => n.replaceWith(...n.childNodes));
  const walker = clone.ownerDocument.createTreeWalker(clone, 128);
  const comments = [];
  while (walker.nextNode()) comments.push(walker.currentNode);
  comments.forEach((c) => c.remove());
  return clone;
}

function blockCopy(document, el) {
  const tag = /^(H[1-6]|P|UL|OL|TABLE|BLOCKQUOTE)$/.test(el.tagName) ? el.tagName.toLowerCase() : 'p';
  const c = clean(el);
  if (tag === el.tagName.toLowerCase()) return c;
  const out = document.createElement(tag);
  out.append(...c.childNodes);
  return out;
}

function termsFromPanel(document, panel) {
  const terms = [];
  const headers = [...panel.querySelectorAll('.citi-rte__para-header')];
  if (headers.length) {
    headers.forEach((h) => {
      const def = [];
      let n = h.nextElementSibling;
      while (n && !n.matches('.citi-rte__para-header')) {
        if (textOf(n)) def.push(blockCopy(document, n));
        n = n.nextElementSibling;
      }
      terms.push({ term: textOf(h).replace(/\s*:\s*$/, ''), def });
    });
    return terms;
  }
  const dts = [...panel.querySelectorAll('dt')];
  if (dts.length) {
    dts.forEach((dt) => {
      const def = [];
      let n = dt.nextElementSibling;
      while (n && n.tagName === 'DD') {
        const p = document.createElement('p');
        p.append(...clean(n).childNodes);
        def.push(p);
        n = n.nextElementSibling;
      }
      terms.push({ term: textOf(dt).replace(/\s*:\s*$/, ''), def });
    });
    return terms;
  }
  // strong-led paragraphs: "<strong>Term:</strong> definition"
  [...panel.querySelectorAll('p')].forEach((p) => {
    const strong = p.querySelector(':scope > strong:first-child, :scope > b:first-child');
    if (strong && textOf(p).startsWith(textOf(strong))) {
      const c = clean(p);
      const s = c.querySelector('strong, b');
      const term = textOf(s).replace(/\s*:\s*$/, '');
      s.remove();
      terms.push({ term, def: textOf(c) ? [c] : [] });
    } else if (terms.length && textOf(p)) {
      terms[terms.length - 1].def.push(clean(p));
    }
  });
  return terms;
}

export default function parse(element, { document, params }) {
  const cells = [];

  // background image (search banner)
  const bannerImg = element.querySelector('.tkc-search-banner-image img, [class*="banner-image"] img');
  const bg = makeImg(document, bannerImg);
  if (bg) cells.push([[bg]]);

  const tabs = element.querySelector('.cmp-tabs, [role="tablist"]');
  const tabsRoot = tabs ? (tabs.closest('.tabs, .cmp-tabs') || tabs) : null;

  // intro: rich text before the tabs (title, disclaimer, sub heading)
  const intro = [];
  const introRtes = [...element.querySelectorAll('.citi-rte')].filter((r) => !tabsRoot || (r.compareDocumentPosition(tabsRoot) & 4));
  introRtes.forEach((rte) => {
    [...rte.children].forEach((child) => {
      if (textOf(child)) intro.push(blockCopy(document, child));
    });
  });
  if (!intro.length) {
    const h = element.querySelector('h1');
    if (h) intro.push(blockCopy(document, h));
  }
  if (intro.length) cells.push([intro]);

  const searchLabel = element.querySelector('label.search-article, .cmp-search label[for], .cmp-search__input[aria-label]');
  const label = searchLabel ? (textOf(searchLabel) || searchLabel.getAttribute('aria-label') || '') : '';
  if (label) cells.push(['Search', label]);

  // terms from every letter panel, in tab order
  let panels = [...element.querySelectorAll('[role="tabpanel"], .cmp-tabs__tabpanel')]
    .filter((p, i, all) => all.indexOf(p) === i && !all.some((o) => o !== p && o.contains(p)));
  if (!panels.length) panels = [element];
  panels.forEach((panel) => {
    termsFromPanel(document, panel).forEach(({ term, def }) => {
      if (!term) return;
      cells.push([term, def.length ? def : '']);
    });
  });

  // outro: content after the tabs (additional resources)
  const outroRoot = element.querySelector('.cmp-experiencefragment, .tkc-additional-resource-container');
  if (outroRoot && textOf(outroRoot) && (!tabsRoot || (tabsRoot.compareDocumentPosition(outroRoot) & 4))) {
    const content = clean(outroRoot);
    const needsBlocks = !!outroRoot.querySelector('.citi-column-control, [class*="tile"], [class*="card"], [class*="column"]');
    if (needsBlocks && params && Array.isArray(params.fragments)) {
      const heading = outroRoot.querySelector('h1, h2, h3');
      const base = pagePath(params) || '/glossary';
      const path = `/fragments/${base.replace(/^\//, '')}/${slugify(textOf(heading) || 'additional-resources')}`;
      params.fragments.push({ element: content, path });
      const a = document.createElement('a');
      a.setAttribute('href', path);
      a.textContent = path;
      cells.push([[a]]);
    } else {
      const nodes = [];
      content.querySelectorAll('h1, h2, h3, h4, h5, h6, p, ul, ol, img').forEach((n) => {
        if (n.tagName === 'IMG') {
          const p = document.createElement('p');
          p.append(n.cloneNode(true));
          nodes.push(p);
        } else if (!n.parentElement.closest('p, ul, ol, h1, h2, h3, h4, h5, h6') && textOf(n)) {
          nodes.push(n.cloneNode(true));
        }
      });
      if (nodes.length) cells.push([nodes]);
    }
  }

  // uniform 2-column table: single-cell rows get an empty second cell? The block
  // treats rows with one non-empty cell as intro/outro, so pad with ''.
  cells.forEach((r) => { while (r.length < 2) r.push(''); });

  const block = WebImporter.Blocks.createBlock(document, { name: 'glossary', cells });
  element.replaceWith(block);
}
